use actix_web::{web, App, HttpServer, HttpResponse, middleware};
use serde::{Deserialize, Serialize};
use std::sync::{Arc, RwLock};
use std::collections::HashMap;

#[derive(Clone, Serialize, Deserialize, Debug)]
pub struct PodMetadata {
    pub name: String,
    pub namespace: String,
    pub labels: Option<HashMap<String, String>>,
    pub annotations: Option<HashMap<String, String>>,
}

#[derive(Clone, Serialize, Deserialize, Debug)]
pub struct HealthStatus {
    pub ready: bool,
    pub last_check_ms: u64,
}

pub struct AppState {
    pub pods: RwLock<HashMap<String, PodMetadata>>,
    pub health_cache: RwLock<HashMap<String, HealthStatus>>,
    pub config: ServiceConfig,
}

#[derive(Clone)]
pub struct ServiceConfig {
    pub namespace_filter: Option<String>,
    pub label_selector: Option<String>,
    pub health_check_interval_ms: u64,
}

impl ServiceConfig {
    pub fn from_env() -> Self {
        ServiceConfig {
            namespace_filter: std::env::var("NAMESPACE_FILTER").ok(),
            label_selector: std::env::var("LABEL_SELECTOR").ok(),
            health_check_interval_ms: std::env::var("HEALTH_CHECK_INTERVAL")
                .unwrap_or_else(|_| "5000".to_string())
                .parse()
                .unwrap_or(5000),
        }
    }
}

fn resolve_pod_identity(metadata: &PodMetadata, config: &ServiceConfig) -> Option<String> {
    // If namespace filter is set, only resolve pods in that namespace
    if let Some(ref ns_filter) = config.namespace_filter {
        if &metadata.namespace != ns_filter {
            return None;
        }
    }

    // If label selector is set, check labels match
    if let Some(ref selector) = config.label_selector {
        let parts: Vec<&str> = selector.splitn(2, '=').collect();
        if parts.len() == 2 {
            let key = parts[0];
            let value = parts[1];
            match &metadata.labels {
                Some(labels) => {
                    if labels.get(key).map(|v| v.as_str()) != Some(value) {
                        return None;
                    }
                }
                None => return None,
            }
        }
    }

    Some(format!("{}/{}", metadata.namespace, metadata.name))
}

fn lookup_health_for_identity(
    identity: Option<String>,
    health_cache: &HashMap<String, HealthStatus>,
) -> HttpResponse {
    // Safely handle the case where identity resolution failed
    let id = match identity {
        Some(id) => id,
        None => {
            return HttpResponse::Forbidden().json(serde_json::json!({
                "error": "pod does not match service filter criteria"
            }));
        }
    };
    match health_cache.get(&id) {
        Some(status) => HttpResponse::Ok().json(status),
        None => HttpResponse::NotFound().json(serde_json::json!({
            "error": "no health data for pod",
            "identity": id
        })),
    }
}

async fn get_pod_health(
    path: web::Path<(String, String)>,
    data: web::Data<Arc<AppState>>,
) -> HttpResponse {
    let (namespace, name) = path.into_inner();

    let pods = data.pods.read().unwrap();
    let pod_key = format!("{}/{}", namespace, name);

    let metadata = match pods.get(&pod_key) {
        Some(m) => m.clone(),
        None => {
            return HttpResponse::NotFound().json(serde_json::json!({
                "error": "pod not found",
                "key": pod_key
            }));
        }
    };
    drop(pods);

    let identity = resolve_pod_identity(&metadata, &data.config);

    let health_cache = data.health_cache.read().unwrap();
    lookup_health_for_identity(identity, &health_cache)
}

async fn register_pod(
    body: web::Json<PodMetadata>,
    data: web::Data<Arc<AppState>>,
) -> HttpResponse {
    let metadata = body.into_inner();
    let key = format!("{}/{}", metadata.namespace, metadata.name);

    let mut pods = data.pods.write().unwrap();
    pods.insert(key.clone(), metadata);

    HttpResponse::Created().json(serde_json::json!({
        "registered": key
    }))
}

async fn update_health(
    path: web::Path<String>,
    body: web::Json<HealthStatus>,
    data: web::Data<Arc<AppState>>,
) -> HttpResponse {
    let identity = path.into_inner();
    let status = body.into_inner();

    let mut health_cache = data.health_cache.write().unwrap();
    health_cache.insert(identity.clone(), status);

    HttpResponse::Ok().json(serde_json::json!({
        "updated": identity
    }))
}

async fn liveness() -> HttpResponse {
    HttpResponse::Ok().json(serde_json::json!({"status": "alive"}))
}

async fn readiness(data: web::Data<Arc<AppState>>) -> HttpResponse {
    let pods = data.pods.read().unwrap();
    if pods.is_empty() {
        HttpResponse::ServiceUnavailable().json(serde_json::json!({
            "status": "not ready",
            "reason": "no pods registered"
        }))
    } else {
        HttpResponse::Ok().json(serde_json::json!({"status": "ready"}))
    }
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    let config = ServiceConfig::from_env();
    let state = Arc::new(AppState {
        pods: RwLock::new(HashMap::new()),
        health_cache: RwLock::new(HashMap::new()),
        config,
    });

    HttpServer::new(move || {
        App::new()
            .app_data(web::Data::new(state.clone()))
            .route("/healthz", web::get().to(liveness))
            .route("/readyz", web::get().to(readiness))
            .route("/api/v1/pods", web::post().to(register_pod))
            .route("/api/v1/pods/{namespace}/{name}/health", web::get().to(get_pod_health))
            .route("/api/v1/health/{identity}", web::put().to(update_health))
    })
    .bind("0.0.0.0:8080")?
    .run()
    .await
}
